/**
 * Hand-labelled evaluation set for the promise/document matcher (hemsida-4np.4).
 * `pairs.json` is generated by `tools/prepare-eval-set.ts` with empty labels; the
 * user fills `label` (and optionally `note`) with `tools/label-eval-set.ts`.
 */
import { z } from 'zod';

export const evalLabelSchema = z.enum(['match', 'partial', 'no_match']);
export type EvalLabel = z.infer<typeof evalLabelSchema>;

export const evalPairSchema = z.object({
  /** Stable key: `<promise_id>::<document_id>`. */
  id: z.string().min(1),
  promise_id: z.string().min(1),
  /** Promise title and description (Swedish, as on the site). */
  promise_title: z.string(),
  promise_text: z.string(),
  promise_quote: z.string(),
  document_id: z.string().min(1),
  document_title: z.string(),
  /** dir, sou, ds, prop or bet. */
  document_type: z.string(),
  /** Short context shown to the labeller: reference, date, committee and which queries found it. */
  snippet: z.string(),
  url: z.string(),
  /** Candidate-search score (number of distinct queries that returned the document). */
  search_score: z.number().int().positive(),
  /** Null until labelled. */
  label: evalLabelSchema.nullable(),
  note: z.string().optional(),
});
export type EvalPair = z.infer<typeof evalPairSchema>;

export const evalFileSchema = z.object({
  term: z.string(),
  seed: z.number().int(),
  pairs: z.array(evalPairSchema),
});
export type EvalFile = z.infer<typeof evalFileSchema>;
